TOOLS = {
    "get_balance": {"params": {"account_id": str}},
    "transfer": {"params": {"to": str, "amount": int}, "confirm": True},
}

def check_call(call):
    spec = TOOLS.get(call["name"])
    if spec is None:
        return "unknown tool"
    for p, t in spec["params"].items():
        if p not in call["args"]:
            return f"missing {p}"
        if not isinstance(call["args"][p], t):
            return f"bad type {p}"
    if spec.get("confirm"):
        return "needs user confirm"
    return "ok"

# get_balance -> ok
