def recall_at_k(results, gold, k=3):
    hit = sum(1 for q, docs in results.items() if gold[q] in docs[:k])
    return hit / len(results)

results = {
    "q1": ["환불규정", "FAQ", "수수료표"],
    "q2": ["이벤트공지", "FAQ", "카드취소안내"],
    "q3": ["FAQ", "수수료표", "이벤트공지"],
}
gold = {"q1": "환불규정", "q2": "카드취소안내", "q3": "환불규정"}
